text:
{
  "title_novice": "Группа 2: столовые рифы и атоллы — край",
  "summary": [
    {"text": "Вторая группа залежей связана с крупными одиночными рифами: столовыми и атоллами.", "claims": ["c1", "c2"]},
    {"text": "Лучшие коллекторы и высокое структурное положение лежат у края рифа, а центр может быть экраном.", "claims": ["c3", "c5"]},
    {"text": "Ловушка простая, а резервуар сложный, поэтому залежь оценивают дополнительными скважинами по периферии.", "claims": ["c6", "c11"]}
  ],
  "claims": [
    {"key": "c1", "text": "Залежи второй группы связаны с одиночными рифами, относительно изометричными или слегка вытянутыми, довольно крупными.", "kind": "observation", "unit_id": "u-220-10c264", "page": 220, "quote": "Залежи второй группы связаны с одиночными относительно изометричными или слегка вытянутыми рифами довольно крупных размеров", "numbers": [], "question": null},
    {"key": "c2", "text": "К группе относятся столовые рифы с плоской вершиной и крутыми склонами и атоллы с периферическими гребнями.", "kind": "observation", "unit_id": "u-220-10c264", "page": 220, "quote": "«столовыми» рифами с плоской вершиной и крутыми склонами и атоллами, причем последние имеют ясно выраженные периферические гребни", "numbers": [], "question": null},
    {"key": "c3", "text": "Лучшие коллекторы находятся в краевых зонах рифов. Центральные части могут быть литологическими экранами.", "kind": "observation", "unit_id": "u-220-10c264", "page": 220, "quote": "Лучшими коллекторскими свойствами обладают краевые зоны этих рифов, их центральные части могут быть даже литологическими экранами", "numbers": [], "question": null},
    {"key": "c4", "text": "Поэтому залежи обычно располагаются в краевых частях рифов, особенно атолловидных.", "kind": "inference", "unit_id": "u-220-10c264", "page": 220, "quote": "В связи с этим залежи обычно располагаются именно в краевых частях рифов, особенно атолловидных", "numbers": [], "question": null},
    {"key": "c5", "text": "Периферические части рифа одновременно имеют лучшие коллекторы и наиболее высокое структурное положение.", "kind": "observation", "unit_id": "u-220-10c264", "page": 220, "quote": "периферические части которых наряду с улучшением коллекторских свойств имеют и наиболее высокое структурное положение", "numbers": [], "question": null},
    {"key": "c6", "text": "Ловушка этой группы относительно проста по форме, а резервуар сложен по строению.", "kind": "inference", "unit_id": "u-220-10c264", "page": 220, "quote": "Таким образом, залежи отличаются относительно простой морфологией ловушки и сложным характером резервуара", "numbers": [], "question": null},
    {"key": "c7", "text": "Разведку рифов этой группы обычно начинают с бурения центральных частей.", "kind": "observation", "unit_id": "u-220-ff2c3f", "page": 220, "quote": "Разведка рифов этой группы, как правило, начинается также с разбирания их центральных частей", "numbers": [], "question": null},
    {"key": "c8", "text": "Из-за сложного распределения коллекторов даже найденная первыми скважинами залежь может не поддаваться оценке.", "kind": "inference", "unit_id": "u-220-ff2c3f", "page": 220, "quote": "сложное распределение коллекторов ведет к тому, что даже при обнаружении залежи первыми скважинами", "numbers": [], "question": null},
    {"key": "c9", "text": "Залежь первыми скважинами находят не всегда: это зависит от плотности внутририфовых и лагунных отложений.", "kind": "observation", "unit_id": "u-220-ff2c3f", "page": 220, "quote": "в связи с плотностью внутририфовых и лагунных отложений это случается далеко не всегда", "numbers": [], "question": null},
    {"key": "c10", "text": "Оценить залежь и тем более составить проект разведки по первым скважинам нельзя.", "kind": "inference", "unit_id": "u-220-ff2c3f", "page": 220, "quote": "оценить ее и тем более составить проект разведки невозможно", "numbers": [], "question": null},
    {"key": "c11", "text": "Для предварительной оценки залежи нужно бурить дополнительные оценочные скважины по периферии ловушки.", "kind": "inference", "unit_id": "u-220-ff2c3f", "page": 220, "quote": "Для проведения предварительной оценки и выявления особенностей строения залежей необходимо бурение дополнительных оценочных скважин по периферии ловушки", "numbers": [], "question": null},
    {"key": "c12", "text": "Если данные указывают на крупный плосковершинный или атолловидный риф, первые скважины ставят на периферии предполагаемой ловушки.", "kind": "assumption", "unit_id": "u-220-ff2c3f", "page": 220, "quote": "Если геологические и геофизические материалы дают возможность предполагать наличие относительно крупного плосковершинного или атолловидного рифа, имеет смысл уже первые скважины располагать на периферии предполагаемой ловушки", "numbers": [], "question": null},
    {"key": "c13", "text": "В этом случае бурение в центре переносят на второй этап оценочных работ.", "kind": "inference", "unit_id": "u-220-ff2c3f", "page": 221, "quote": "а бурение в центре отнести ко второму этапу оценочных работ", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Залежи этой группы связаны с одиночными рифами, которые в плане примерно изометричны или слегка вытянуты.", "claims": ["c1"], "hypothesis": false},
    {"text": "Это крупные столовые рифы с плоской вершиной и крутыми склонами, а также атоллы с периферическими гребнями.", "claims": ["c2"], "hypothesis": false},
    {"text": "Лучшие коллекторы лежат в краевых зонах. Центр рифа может работать как литологический экран, то есть задерживать флюид.", "claims": ["c3"], "hypothesis": false},
    {"text": "Край рифа при этом расположен выше по структуре. Поэтому залежи чаще собираются именно у края.", "claims": ["c4", "c5"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист сначала смотрит по геологическим и геофизическим данным, не крупный ли это столовый или атолловидный риф.", "claims": ["c12"], "hypothesis": false},
    {"text": "Для такого рифа первые скважины ставят на периферии предполагаемой ловушки, а центр бурят позже.", "claims": ["c12", "c13"], "hypothesis": false},
    {"text": "В обычном случае разведку начинают с центральных частей рифа.", "claims": ["c7"], "hypothesis": false},
    {"text": "Даже найденную залежь нельзя оценить одними первыми скважинами. Нужны оценочные скважины по периферии.", "claims": ["c8", "c10", "c11"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Найти залежь первыми скважинами удаётся не всегда. Мешает плотность внутририфовых и лагунных отложений.", "claims": ["c9"]},
    {"text": "Простая форма ловушки не означает простую разведку. Резервуар внутри рифа остаётся сложным.", "claims": ["c6"]},
    {"text": "Центр рифа может быть экраном, а лучшие коллекторы находятся у края.", "claims": ["c3"]},
    {"text": "Порядок «сначала центр» действует как правило. При предполагаемом крупном столовом или атолловидном рифе порядок меняется.", "claims": ["c7", "c12"]},
    {"text": "Речь идёт об одиночных рифах этой группы, а не о рифовых системах.", "claims": ["c1"]}
  ],
  "deeper": [
    {"title": "Почему одна скважина не даёт картину", "text": "Коллекторы распределены внутри рифа неравномерно: край и центр различаются. Поэтому даже удачная скважина не заменяет оценочные скважины.", "claims": ["c8", "c10"], "hypothesis": false}
  ],
  "procedure": [
    {"text": "Определить по геологическим и геофизическим материалам, не является ли риф крупным плосковершинным или атолловидным.", "claims": ["c12"]},
    {"text": "Если да: первые скважины ставить на периферии предполагаемой ловушки.", "claims": ["c12"]},
    {"text": "Бурение в центре отнести ко второму этапу оценочных работ.", "claims": ["c13"]},
    {"text": "В обычном случае начинать разведку с бурения центральных частей рифа.", "claims": ["c7"]},
    {"text": "Если залежь найдена, провести предварительную оценку дополнительными оценочными скважинами по периферии ловушки.", "claims": ["c9", "c11"]}
  ],
  "numbers_conditions": [
    {"text": "Условие группы: одиночный риф, относительно изометричный или слегка вытянутый, довольно крупный.", "claims": ["c1"]},
    {"text": "Условие периферийного бурения: риф предполагается крупным плосковершинным или атолловидным.", "claims": ["c12"]},
    {"text": "Центр бурят на втором этапе оценочных работ, если первые скважины ставили на периферии.", "claims": ["c13"]},
    {"text": "Залежь первыми скважинами находят не всегда: зависит от плотности внутририфовых и лагунных отложений.", "claims": ["c9"]}
  ],
  "terms_defined": [
    {"term": "оценочная скважина", "term_en": "appraisal well", "abbr": "", "definition": "Скважина, которую бурят, чтобы предварительно оценить залежь и выяснить особенности её строения. Ставят по периферии ловушки.", "claims": ["c11"]},
    {"term": "изометричный", "term_en": "isometric", "abbr": "", "definition": "Примерно одинаковый по размерам в разных направлениях.", "claims": ["c1"]},
    {"term": "краевая зона рифа", "term_en": "reef margin zone", "abbr": "", "definition": "Внешняя часть рифа, близкая к его краю.", "claims": ["c3"]},
    {"term": "периферический гребень", "term_en": "peripheral crest", "abbr": "", "definition": "Выраженный гребень по внешнему краю атолла.", "claims": ["c2"]},
    {"term": "структурное положение", "term_en": "structural position", "abbr": "", "definition": "Высота участка в общем строении залежи относительно соседних участков.", "claims": ["c5"]},
    {"term": "внутририфовые отложения", "term_en": "intra-reef deposits", "abbr": "", "definition": "Отложения внутри рифового массива.", "claims": ["c9"]}
  ],
  "terms_used": ["риф", "залежь", "ловушка", "коллекторские свойства", "резервуар", "природный резервуар (ПР)", "атолл", "атолловидный риф", "столовый риф", "одиночный риф", "плосковершинный риф", "рифовый гребень", "лагуна", "лагунные отложения", "экран", "литологический экран", "разведка", "проект разведки", "скважина", "геофизические материалы"],
