  "data_meaning": {
    "inputs": [
      {"text": "Геологические и геофизические материалы: признаки крупного столового рифа или атолла.", "claims": ["c12"], "hypothesis": false},
      {"text": "Результат первых скважин: нашли ли залежь в центре или на периферии.", "claims": ["c9"], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Решение, где ставить первые скважины: на периферии предполагаемой ловушки или в центре.", "claims": ["c12", "c13"], "hypothesis": false},
      {"text": "Набор оценочных скважин по периферии для предварительной оценки залежи.", "claims": ["c11"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Залежь первыми скважинами не всегда обнаруживается из-за плотности внутририфовых и лагунных отложений.", "claims": ["c9"], "hypothesis": false},
      {"text": "Правило периферийного бурения опирается на предположение о крупном столовом или атолловидном рифе. Иначе порядок другой.", "claims": ["c12", "c7"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Как пилотный запуск функции: один успешный пилот в центре мало. Нужны пилоты по краям, чтобы оценить систему целиком.",
    "breaks_where": "Пилот в ИТ обычно дёшев и повторяем. Скважина дорога и необратима, поэтому порядок бурения важен."
  },
